        trigger: "Uma criatura no alcance usa uma ação de manipular ou de movimento, faz um ataque à distância, ou sai de um quadrado durante uma ação de movimento que está usando.",
        description: "O faraó múmia pode usar Golpe Reativo quando uma criatura no alcance usa uma ação de concentração, além do gatilho normal. Pode interromper ações de concentração disparadoras, e interrompe ações em qualquer acerto, não só em acerto crítico.\n\nA criatura tenta um Golpe corpo a corpo contra quem disparou. Se o ataque for um acerto crítico e o gatilho foi uma ação de manipular, a criatura interrompe essa ação. Este Golpe não conta para a penalidade de ataques múltiplos, e essa penalidade não se aplica a este Golpe.",
