        description: "Quando uma criatura causa dano físico ao faraó ou dispara uma das fraquezas do faraó, precisa passar em Vontade CD 28 ou fica Condenada 1.\nIndependente do resultado da salvaguarda, a criatura fica imune às faixas sagradas daquela múmia por 24 horas.",
