        description: "Areia gira ao redor do faraó múmia numa emanação de 1,5 m até o início do próximo turno. Criaturas dentro da areia ficam Ocultas para quem está fora, e qualquer criatura viva que termine o turno na areia sofre 4d6 de dano de fogo com Fortitude CD 28.\nVéu de Areia termina se a múmia sofrer dano da fraqueza a água.",
