        description: "Um colhedor de crânios recorre às memórias das criaturas cujos ossos formam o corpo. Isso concede a perícia Saber Esquelético, que pode usar para Recordar Conhecimento de qualquer tipo. Além disso, pode falar e entender todos os idiomas conhecidos pelas criaturas cujos ossos formam o corpo (em geral incluindo Comum e o idioma regional da terra natal).\nO colhedor de crânios pode usar Saber Esquelético como teste de perícia primário para o ritual Memórias Coletivas, e pode conjurar memórias coletivas sem conjuradores secundários.",
