        description: "3 m.\nUma nuvem de estilhaços ósseos cerca o colhedor de crânios. Quando uma criatura se move para a emanação ou começa o turno ali, a tempestade causa 4d6 cortante e 4d6 de vazio, com Reflexos CD 40.\nSe a criatura tiver resistência ou imunidade a dano de vazio, ou um efeito que a proteja contra efeitos de morte, ou um efeito que a proteja contra as condições Condenado ou Drenado, primeiro precisa passar em Vontade CD 40 ou ter todos esses benefícios suprimidos por 1 minuto.",
