        name: "Solo Estilhaçado",
        originalName: "Splintered Ground",
        actionType: "one",
        description: "O colhedor de crânios faz ossos estilhaçados irromperem de todas as superfícies sólidas numa emanação de 30 m, exceto superfícies de pedra trabalhada. Uma criatura que se mova pelos ossos sofre 10 de dano perfurante e 10 de vazio para cada 1,5 m de movimento.\nNa primeira vez a cada rodada que uma criatura sofrer dano perfurante desses ossos, precisa passar em Reflexos CD 40 ou sofre penalidade de circunstância de –3 m a todos os Deslocamentos por 10 minutos, ou –4,5 m por 24 horas em falha crítica.\nOs ossos permanecem no lugar até o colhedor usar esta ação de novo ou até serem removidos manualmente, o que leva 10 minutos para cada quadrado de 1,5 m.",
