        description: "O gigante das nuvens Golpeia uma criatura com o ranseur, cercado num rugido de ar em disparada. Em acerto, o alvo sofre 4d8 adicional de concussão e fica Surdo por 1 minuto. Acertando ou não, cada criatura que não seja gigante das nuvens numa emanação de 6 m, inclusive o alvo do Golpe, é açoitada por ventos rugidores e precisa tentar Fortitude CD 30.\nSucesso crítico a criatura não é afetada.\nSucesso a criatura sofre 2d8 de concussão.\nFalha a criatura sofre 4d8 de concussão e fica Surda até o fim do próximo turno.\nFalha crítica como falha, mas dano dobrado e também Caída.",
