        description: "Salvaguarda Fortitude CD 34\nDuração máxima 10 rodadas\nEstágio 1 4d6 de fogo e Drenado 1 (1 rodada)\nEstágio 2 6d6 de fogo e Drenado 2 (1 rodada)",
