        name: "Aura de Infestação",
        originalName: "Infestation Aura",
        actionType: "passive",
        description: "36 m.\nEnquanto o núcleo estiver implantado, um grikkitog infesta toda terra e pedra a até 36 m, desde que haja conexão física contínua, inclusive objetos de pedra tocando o chão. Este efeito se espalha mesmo sem linha de efeito, embora só possa afetar terra ou pedra na superfície e exposta ao ar se pelo menos parte do núcleo também estiver exposta.\nDentro da aura, pode crescer goelas e olhos por toda parte. Pode fazer ataques de mandíbulas contra qualquer criatura, originando-se de qualquer terra ou pedra na aura adjacente àquela criatura. Determine cobertura a partir do ponto de origem do ataque, não do núcleo do grikkitog.",
