        trigger: "O mukradi ficaria Confuso, Amedrontado, Paralisado ou Atordoado",
        description: "O mukradi confina o efeito debilitante a uma porção do sistema nervoso, ignorando o efeito mas fazendo uma goela à escolha ficar dormente pela duração do efeito. Essa goela não pode ser usada para um Golpe nem para Soprar Energia nesse tempo. Esta habilidade não pode ser usada se todas as cabeças do mukradi estiverem dormentes.",
