        description: "O mukradi faz dois Golpes com goelas diferentes contra o mesmo alvo. Se ambos acertarem, o alvo sofre 2d12+13 adicional de cortante, com Fortitude CD 36. Em falha crítica, a criatura é rasgada em pedaços e morre.\nA penalidade de ataques múltiplos do mukradi só aumenta depois de todos os ataques.",
