        name: "Debater-se",
        originalName: "Thrash",
        actionType: "two",
        description: "O mukradi Golpeia uma vez contra cada criatura no alcance. Pode fazer um desses Golpes com cada goela, um com o chicote de cauda, e o resto com as patas. Cada ataque sofre penalidade de circunstância de –2 e conta para a penalidade de ataques múltiplos, mas essa penalidade só aumenta depois de todos os ataques.",
