        name: "Lacaios Aranha",
        originalName: "Spider Minions",
        actionType: "three",
        description: "A morrigna conjura uma tarântula gigante ou uma aranha caçadora. Essas aranhas têm o traço conjurado e permanecem por 10 minutos ou até reduzidas a 0 PV, o que ocorrer primeiro. A morrigna não precisa Sustentar a Magia para dirigir essas criaturas conjuradas, e pode ter qualquer número de aranhas conjuradas ao mesmo tempo. A morrigna pode ver pelos olhos de qualquer uma das aranhas conjuradas a qualquer momento.",
